INSERT INTO tmp_import_scenic (name, description, image_url, latitude, longitude, location, radius, is_deleted, created_at, updated_at) VALUES
('1教', '文学院所在地，建于1950年代，典型苏式建筑，灰白色墙面配绿色木窗，三层对称结构，楼前有石阶和老树。为纪念国学大师吴宓（字雨僧）命名，是西大的精神地标。内部走廊宽阔，教室保留了老式长条木地板。', '/download/scenic/teaching-import/spot-01.png', 29.8259080, 106.4287999, ST_GeomFromText('POINT(29.8259080 106.4287999)', 4326), 60, 0, NOW(), NOW()),
('3教', '分前后两栋：前楼1955年青瓦白墙仿古风格，后楼2007年现代风格，现为国家治理学院和马克思主义学院。', '/download/scenic/teaching-import/spot-02.jpg', 29.8268691, 106.4279271, ST_GeomFromText('POINT(29.8268691 106.4279271)', 4326), 60, 0, NOW(), NOW()),
('4教', '西大最老教学楼之一，分A（1956年）、B（1999年）两栋，现为新闻传媒学院，外墙爬满爬山虎。', '/download/scenic/teaching-import/spot-03.jpg', 29.8230759, 106.4266786, ST_GeomFromText('POINT(29.8230759 106.4266786)', 4326), 60, 0, NOW(), NOW()),
('7教', '五层公共教学楼，灰色水刷石外墙，建于1980年代。教室以中型阶梯教室为主，日常排课率高。楼下有快餐亭和自动售货机，课间人流量很大。', '/download/scenic/teaching-import/spot-04.jpg', 29.8222331, 106.4268796, ST_GeomFromText('POINT(29.8222331 106.4268796)', 4326), 60, 0, NOW(), NOW()),
('9教', '原外国语学院旧址，现为外语教学资源中心和历史地理研究所。五层砖混结构，外墙爬满爬山虎，夏季绿意盎然。内部藏有大量外文原版书籍和文献资料。', '/download/scenic/teaching-import/spot-05.jpg', 29.8264787, 106.4295726, ST_GeomFromText('POINT(29.8264787 106.4295726)', 4326), 60, 0, NOW(), NOW()),
('10教', '以 “时空隧道” 出名——正门进去直接是5楼，往下走4层才是1楼，完美体现重庆魔幻地形。建筑依山而建，外观呈不规则几何形，内部走廊曲折。是游客打卡拍照的热门地点。', '/download/scenic/teaching-import/spot-06.jpg', 29.8271231, 106.4289888, ST_GeomFromText('POINT(29.8271231 106.4289888)', 4326), 60, 0, NOW(), NOW()),
('15教', '美术学院所在地，外观设计独特，外墙饰有抽象艺术图案。楼内有画室、雕塑工作室和美术馆展厅，每年毕业季举办学生作品展。', '/download/scenic/teaching-import/spot-07.jpg', 29.8225059, 106.4296758, ST_GeomFromText('POINT(29.8225059 106.4296758)', 4326), 60, 0, NOW(), NOW()),
('17教', '文化与社会发展学院，五层建筑，外墙灰色。一楼设有社会工作专业实验室和模拟法庭。', '/download/scenic/teaching-import/spot-08.jpg', 29.8297429, 106.4329095, ST_GeomFromText('POINT(29.8297429 106.4329095)', 4326), 60, 0, NOW(), NOW()),
('19教', '音乐学院办公楼，同时设有音乐厅，可容纳300人，经常举办音乐会和汇报演出。', '/download/scenic/teaching-import/spot-09.jpg', 29.8210245, 106.4271976, ST_GeomFromText('POINT(29.8210245 106.4271976)', 4326), 60, 0, NOW(), NOW()),
('21教', '汉语言文献研究所，三层灰色小楼。收藏有大量古籍和出土文献复制本，是汉语言研究的重要基地。', '/download/scenic/teaching-import/spot-10.jpg', 29.8196388, 106.4224109, ST_GeomFromText('POINT(29.8196388 106.4224109)', 4326), 60, 0, NOW(), NOW()),
('23教', '心理学部主楼，八层建筑，西大优势学科所在地。楼内拥有核磁共振成像（fMRI）实验室和认知行为实验室。', '/download/scenic/teaching-import/spot-11.jpg', 29.8210174, 106.4219690, ST_GeomFromText('POINT(29.8210174 106.4219690)', 4326), 60, 0, NOW(), NOW()),
('24教', '地理科学学院，半圆形建筑，外观独特，像半个圆环。与26、27、28教共同组成 “三星抱月” 布局。楼顶设有气象观测站。', '/download/scenic/teaching-import/spot-12.jpg', 29.8217494, 106.4230487, ST_GeomFromText('POINT(29.8217494 106.4230487)', 4326), 60, 0, NOW(), NOW()),
('25教', '西大最高的教学楼，共15层，外形酷似一个大 “U盘”，是北区的地标建筑。理科实验室集中地，楼内有电梯，高层可俯瞰整个北区校园。', '/download/scenic/teaching-import/spot-13.jpg', 29.8227444, 106.4240913, ST_GeomFromText('POINT(29.8227444 106.4240913)', 4326), 60, 0, NOW(), NOW()),
('26教', '紧邻7教的一座三层小楼，外墙刷浅黄色涂料。楼内设有考研专用自习室，因环境安静、座位充足，成为考研学生的“根据地”。楼上窗口可以俯瞰北区主干道。', '/download/scenic/teaching-import/spot-14.jpg', 29.8229172, 106.4218669, ST_GeomFromText('POINT(29.8229172 106.4218669)', 4326), 60, 0, NOW(), NOW()),
('27教', '五层公共教学楼，灰色水刷石外墙，建于1980年代。教室以中型阶梯教室为主，日常排课率高。楼下有快餐亭和自动售货机，课间人流量很大。', '/download/scenic/teaching-import/spot-15.jpg', 29.8233669, 106.4225577, ST_GeomFromText('POINT(29.8233669 106.4225577)', 4326), 60, 0, NOW(), NOW()),
('28教', '三栋相连的公共教学楼，位于梅园附近。每栋四层，通过连廊相通，与24教共同构成 “三星抱月” 景观。教室以合班大课教室为主。', '/download/scenic/teaching-import/spot-16.jpg', 29.8236715, 106.4231695, ST_GeomFromText('POINT(29.8236715 106.4231695)', 4326), 60, 0, NOW(), NOW()),
('30教', '以平民教育家晏阳初命名。六层公共教学楼，白色外墙，正门朝南。设有语音实验室，是四六级口语考试的指定考点。', '/download/scenic/teaching-import/spot-17.jpg', 29.8117433, 106.4176696, ST_GeomFromText('POINT(29.8117433 106.4176696)', 4326), 60, 0, NOW(), NOW()),
('31教', '以土壤学家侯光炯（字兆畦）命名。南区最主要的公共教学楼之一，五层，灰色外墙，日均人流量近2000人。教室以中型教室为主，一至四层上课，五层为教师办公室。', '/download/scenic/teaching-import/spot-18.jpg', 29.8142494, 106.4208636, ST_GeomFromText('POINT(29.8142494 106.4208636)', 4326), 60, 0, NOW(), NOW()),
('32教', '楼名寓意“弘扬大学精神，奉献勤奋”。南区最大的公共教学楼，六层，浅黄色外墙。设有多个大型阶梯教室，是南区考研专用考点楼。', '/download/scenic/teaching-import/spot-19.jpg', 29.8136471, 106.4174936, ST_GeomFromText('POINT(29.8136471 106.4174936)', 4326), 60, 0, NOW(), NOW()),
('34教', '植物保护学院，四层建筑，外墙白色。楼内设有昆虫标本室和植物病理实验室。', '/download/scenic/teaching-import/spot-20.jpg', 29.8123767, 106.4180515, ST_GeomFromText('POINT(29.8123767 106.4180515)', 4326), 60, 0, NOW(), NOW()),
('37教', '动物科技学院、农学与生物科技学院共用。四层建筑，外墙米黄色。楼内设有动物解剖室和分子生物学实验室。', '/download/scenic/teaching-import/spot-21.jpg', 29.8129685, 106.4168718, ST_GeomFromText('POINT(29.8129685 106.4168718)', 4326), 60, 0, NOW(), NOW()),
('43教', '以“杂交水稻之父”袁隆平校友命名。生物技术大楼，六层，外墙灰白色。农学相关实验室集中地，设有植物组织培养室和人工气候室。', '/download/scenic/teaching-import/spot-22.jpg', 29.8128493, 106.4156291, ST_GeomFromText('POINT(29.8128493 106.4156291)', 4326), 60, 0, NOW(), NOW()),
('45教', '纺织服装学院，五层建筑，外墙灰色。目前所知编号最大的教学楼。楼内设有服装设计工作室、纺织检测实验室和缝纫工艺车间。', '/download/scenic/teaching-import/spot-23.jpg', 29.8139535, 106.4168987, ST_GeomFromText('POINT(29.8139535 106.4168987)', 4326), 60, 0, NOW(), NOW()),
('中心图书馆', '2012年建成，地上15层，是西南地区最大的图书馆之一。外观呈方形，外墙为玻璃幕墙。藏书数百万册，设有自习区、研讨室、咖啡厅，是北区的核心建筑。', '/download/scenic/teaching-import/spot-24.jpg', 29.8208438, 106.4244343, ST_GeomFromText('POINT(29.8208438 106.4244343)', 4326), 60, 0, NOW(), NOW()),
('崇实图书馆', '暂无简介', '/download/scenic/teaching-import/spot-25.jpg', 29.8133877, 106.4190782, ST_GeomFromText('POINT(29.8133877 106.4190782)', 4326), 60, 0, NOW(), NOW()),
('鉴知楼', '暂无简介', '/download/scenic/teaching-import/spot-26.jpg', 29.8182613, 106.4218921, ST_GeomFromText('POINT(29.8182613 106.4218921)', 4326), 60, 0, NOW(), NOW()),
('君展楼', '暂无简介', '/download/scenic/teaching-import/spot-27.jpg', 29.8252551, 106.4309973, ST_GeomFromText('POINT(29.8252551 106.4309973)', 4326), 60, 0, NOW(), NOW()),
('同心楼', '暂无简介', '/download/scenic/teaching-import/spot-28.jpg', 29.8241344, 106.4302886, ST_GeomFromText('POINT(29.8241344 106.4302886)', 4326), 60, 0, NOW(), NOW()),
('紫云楼', '暂无简介', '/download/scenic/teaching-import/spot-29.jpg', 29.8292222, 106.4301383, ST_GeomFromText('POINT(29.8292222 106.4301383)', 4326), 60, 0, NOW(), NOW());
INSERT INTO scenic_spots (name, description, image_url, audio_url, latitude, longitude, location, radius, is_deleted, created_at, updated_at) SELECT t.name,t.description,t.image_url,NULL,t.latitude,t.longitude,t.location,t.radius,t.is_deleted,t.created_at,t.updated_at FROM tmp_import_scenic t WHERE NOT EXISTS (SELECT 1 FROM scenic_spots s WHERE s.name=t.name AND s.is_deleted=0);
