USE smart_guide_db;
CREATE TEMPORARY TABLE tmp_import_scenic (name VARCHAR(100) NOT NULL, description TEXT NOT NULL, image_url VARCHAR(512), latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, location POINT NOT NULL SRID 4326, radius INT NOT NULL, is_deleted TINYINT(1) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);

UPDATE scenic_spots s JOIN tmp_import_scenic t ON s.name=t.name AND s.is_deleted=0 SET s.description=t.description, s.image_url=t.image_url, s.audio_url=NULL, s.latitude=t.latitude, s.longitude=t.longitude, s.location=t.location, s.radius=t.radius, s.updated_at=NOW();
DROP TEMPORARY TABLE tmp_import_scenic;
